mapper.select:
SELECT login_history_id, factory_code, user_id, user_name, to_char(login_dt, 'YYYY-MM-DD HH24:MI:SS') AS login_dt, login_ip, login_type, user_agent, login_result, fail_reason, to_char(logout_dt, 'YYYY-MM-DD HH24:MI:SS') AS logout_dt, session_time, gov_interface_yn, to_char(gov_interface_dt, 'YYYY-MM-DD HH24:MI:SS') AS gov_interface_dt, gov_recptn_rslt_cd, gov_recptn_rslt, gov_recptn_rslt_dtl, gov_fail_reason, gov_request_json, gov_response_json FROM ( SELECT *, ROW_NUMBER() OVER (ORDER BY login_dt DESC) AS rnum FROM TB_LoginHistory WHERE factory_code = #{factoryCode}
AND user_id ILIKE '%' || #{searchUserId} || '%'
AND user_name ILIKE '%' || #{searchUserName} || '%'
AND login_result = #{searchLoginResult}
AND login_dt >= #{searchStartDt}::timestamp
AND login_dt <= (#{searchEndDt}::timestamp + INTERVAL '1 day')
) AS temp WHERE rnum BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage} ORDER BY login_dt DESC

SELECT COUNT(*) AS cnt FROM TB_LoginHistory WHERE factory_code = #{factoryCode}
AND user_id ILIKE '%' || #{searchUserId} || '%'
AND user_name ILIKE '%' || #{searchUserName} || '%'
AND login_result = #{searchLoginResult}
AND login_dt >= #{searchStartDt}::timestamp
AND login_dt <= (#{searchEndDt}::timestamp + INTERVAL '1 day')
